Skill 0 looks like max(f(a),g(b)) and skill 3 like min(f(a),g(b)), while skills 1 and 2 look additive and clipped; I group identical rows and columns and print the reduced tables sorted by mean.

```python
import numpy as np
def silu(x): return x/(1+np.exp(-x))
def fwd(W,X):
    h=silu(X@W['l1.weight'].T+W['l1.bias']); h=silu(h@W['l2.weight'].T+W['l2.bias']); return h@W['l3.weight'].T+W['l3.bias']
def inputs(s):
    a,b=np.meshgrid(np.arange(32),np.arange(32),indexing='ij'); a=a.ravel();b=b.ravel()
    X=np.zeros((1024,68));X[np.arange(1024),a]=1;X[np.arange(1024),32+b]=1;X[:,64+s]=1
    return X
W={n:load(n) for n in NAMES}
def groups(M,thr):
    # single pass: join a row to the first group whose founder differs in at most thr entries
    g=[];lab=-np.ones(len(M),int)
    for i,r in enumerate(M):
        for j,f in enumerate(g):
            if (r!=M[f]).sum()<=thr: lab[i]=j;break
        else:
            g.append(i);lab[i]=len(g)-1
    return lab
def mode(x): return np.bincount(x,minlength=8).argmax()
for s in range(4):
    p=fwd(W,inputs(s)).argmax(1).reshape(32,32)
    rl=groups(p,4); cl=groups(p.T,4)
    R=np.array([[mode(p[np.ix_(rl==i,cl==j)].ravel()) for j in range(cl.max()+1)] for i in range(rl.max()+1)])
    ro=np.argsort(R.mean(1));co=np.argsort(R.mean(0))
    print('skill',s,'row groups',rl.max()+1,'col groups',cl.max()+1)
    print('rows by group',[np.where(rl==i)[0].tolist() for i in ro])
    print('cols by group',[np.where(cl==j)[0].tolist() for j in co])
    for r in R[ro][:,co]: print(''.join(map(str,r)))
    rec=R[rl][:,cl]; print('cells differing from group table',(rec!=p).sum(),'of 1024')
    logit=fwd(W,inputs(s)); print('max class logit above 7?', (logit[:,8:].max()-logit[:,:8].max()))
